import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# EDA
try:
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS (non-target pairs, |r| >= 0.2)
try:
    num_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    corr_matrix = df[num_cols].corr(method='pearson')
    pairs = {}
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                pairs[f'{c1}__{c2}'] = round(float(r), 4)
    result['correlations'].update(pairs)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for seg in seg_cols:
        top_groups = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top_groups)]
        for metric in metric_cols:
            for agg, agg_name in [('mean', 'mean'), ('sum', 'sum')]:
                grp = sub.groupby(seg)[metric].agg(agg)
                result['segments'].append({
                    'segment_column': seg,
                    'metric_column': metric,
                    'aggregation': agg_name,
                    'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
                })
    # Count per segment
    for seg in seg_cols:
        top_groups = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top_groups)]
        grp = sub.groupby(seg)['order_id'].count()
        result['segments'].append({
            'segment_column': seg,
            'metric_column': 'order_id',
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # Two-column breakdown: segment x region
    df['_seg_reg'] = df['segment'].astype(str) + '|' + df['region'].astype(str)
    top2 = df['_seg_reg'].value_counts().head(10).index
    sub2 = df[df['_seg_reg'].isin(top2)]
    for metric in metric_cols:
        grp2 = sub2.groupby('_seg_reg')[metric].mean()
        result['segments'].append({
            'segment_column': 'segment|region',
            'metric_column': metric,
            'aggregation': 'mean',
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp2.items()]
        })
except Exception:
    pass

# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    metric_cols_a = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols_a:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_t) - shift)
                hi_orig = float(np.expm1(hi_t) - shift)
            else:
                lo_orig, hi_orig = lo_t, hi_t
            anomaly_records.append({
                'column': col, 'row_index': None,
                'value': None,
                'expected_range': f'[{lo_orig:.4g}, {hi_orig:.4g}]',
                'severity': 'low',
                'explanation': f'Column {col} is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary'
            })
            continue
        flagged_idx = s_t[mask].index
        for idx in flagged_idx:
            if len(anomaly_records) >= 25:
                break
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_t) - shift)
                hi_orig = float(np.expm1(hi_t) - shift)
            else:
                lo_orig, hi_orig = lo_t, hi_t
            lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
            lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
            if t_val > q3 + 5 * iqr or t_val < q1 - 5 * iqr:
                sev = 'critical'
            elif t_val > q3 + 4 * iqr or t_val < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo_orig:.4g}, {hi_orig:.4g}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx),
                'value': raw_val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f'Value {raw_val} in column {col} lies outside expected range {exp_range}'
            })
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records
except Exception:
    pass

# TRENDS (7d rolling and YoY if applicable)
try:
    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df_t = df.set_index('order_date').sort_index()
    for metric in ['revenue', 'units', 'discount', 'marketing_spend']:
        daily = df_t[metric].resample('D').mean()
        rolling = daily.rolling(7).mean().dropna()
        if len(rolling) >= 2:
            first_val = float(rolling.iloc[0])
            last_val = float(rolling.iloc[-1])
            if first_val != 0:
                pct = round((last_val - first_val) / abs(first_val) * 100, 2)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': '7d_rolling',
                'direction': direction, 'pct_change': pct, 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly revenue)
try:
    import numpy as np
    from scipy import stats as sp_stats
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly = df.groupby('_ym')['revenue'].sum().reset_index()
    monthly['_t'] = range(len(monthly))
    if len(monthly) >= 3:
        slope, intercept, r, p, se = sp_stats.linregress(monthly['_t'], monthly['revenue'])
        last_t = int(monthly['_t'].max())
        last_period = monthly['_ym'].max()
        forecast_pts = []
        for i in range(1, 4):
            t_i = last_t + i
            val = float(intercept + slope * t_i)
            period_label = str(last_period + i)
            forecast_pts.append({'period': period_label, 'value': round(val, 2)})
        result['forecast_points'] = forecast_pts
        r_val = round(float(r), 4)
        p_val = round(float(p), 6)
        interp = f'Linear trend fit: r={r_val}, p={p_val}'
        result['statistical_tests'].append({
            'test_name': 'Linear regression (monthly revenue trend)',
            'statistic': round(float(slope), 4),
            'p_value': p_val,
            'interpretation': interp
        })
except Exception:
    pass

result['assumptions'] = [
    'Duplicate rows (25) were removed prior to analysis.',
