# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    metric_cols_a = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols_a:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_t) - shift)
                hi_orig = float(np.expm1(hi_t) - shift)
            else:
                lo_orig, hi_orig = lo_t, hi_t
            anomaly_records.append({
                'column': col, 'row_index': None,
                'value': None,
                'expected_range': f'[{lo_orig:.4g}, {hi_orig:.4g}]',
                'severity': 'low',
                'explanation': f'Column {col} is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary'
            })
            continue
        flagged_idx = s_t[mask].index
        for idx in flagged_idx:
            if len(anomaly_records) >= 25:
                break
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_t) - shift)
                hi_orig = float(np.expm1(hi_t) - shift)
            else:
                lo_orig, hi_orig = lo_t, hi_t
