        for metric in numeric_cols:
            grp = sub.groupby(seg_col)[metric].mean()
            seg_results.append({
                "segment_column": seg_col,
                "metric_column": metric,
                "aggregation": "mean",
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg_col)[numeric_cols[0]].count()
        seg_results.append({
            "segment_column": seg_col,
            "metric_column": numeric_cols[0],
            "aggregation": "count",
            "results": [{"name": str(k), "value": float(v)} for k, v in cnt.items()]
        })
    # Joint breakdown segment x region
    df['_seg_reg'] = df['segment'].astype(str) + '|' + df['region'].astype(str)
    top_joint = df['_seg_reg'].value_counts().head(10).index
    sub_j = df[df['_seg_reg'].isin(top_joint)]
    for metric in numeric_cols:
        grp_j = sub_j.groupby('_seg_reg')[metric].mean()
        seg_results.append({
            "segment_column": "segment|region",
            "metric_column": metric,
            "aggregation": "mean",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp_j.items()]
        })
    result['segments'] = seg_results
except Exception:
    pass

# ANOMALIES
try:
    anomalies = []
    total_cap = 25
    for col in numeric_cols:
        if total_cap <= 0:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()
        q1, q3 = float(s_work.quantile(0.25)), float(s_work.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_work < lo3) | (s_work > hi3)
        flagged_idx = s_work[mask].index.tolist()
        if len(flagged_idx) / len(s) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"[{float(s.quantile(0.25)):.2f}, {float(s.quantile(0.75)):.2f}]",
                "severity": "low",
                "explanation": f"Column {col} is heavy-tailed; extreme-value rate exceeds 5%, not flagged individually."
            })
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = lo3, hi3
        exp_range = f"[{orig_lo:.2f}, {orig_hi:.2f}]"
        for idx in flagged_idx[:total_cap]:
            val = float(df.loc[idx, col])
            w = float(s_work[idx])
            if w > hi5 or w < lo5:
                sev = "critical"
            elif w > hi4 or w < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"Value {val:.4f} in column {col} lies outside expected range {exp_range}."
            })
            total_cap -= 1
            if total_cap <= 0:
                break
    result['anomalies'] = anomalies
except Exception:
    pass

# TRENDS (7d rolling + MoM for non-target-pair metrics)
try:
    df[date_col] = pd.to_datetime(df[date_col])
    df_t = df.set_index(date_col).sort_index()
    trends = []
    for col in numeric_cols:
        daily = df_t[col].resample('D').mean()
        roll = daily.rolling(7).mean().dropna()
        if len(roll) >= 2:
            first7 = float(roll.iloc[0])
            last7 = float(roll.iloc[-1])
            if first7 != 0:
                pct = round((last7 - first7) / abs(first7) * 100, 2)
            else:
                pct = 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": col, "period": "7d_rolling", "direction": direction,
                           "pct_change": pct, "segment": None})
        monthly = df_t[col].resample('ME').mean()
        if len(monthly) >= 2:
            prev_val = float(monthly.iloc[-2])
            curr_val = float(monthly.iloc[-1])
            if prev_val != 0:
                pct_m = round((curr_val - prev_val) / abs(prev_val) * 100, 2)
            else:
                pct_m = 0.0
            direction_m = "up" if pct_m > 1 else ("down" if pct_m < -1 else "flat")
            trends.append({"column": col, "period": "MoM", "direction": direction_m,
                           "pct_change": pct_m, "segment": None})
    result['trends'] = trends
except Exception:
    pass

# FORECASTING (simple linear extrapolation, next 3 months)
try:
    df[date_col] = pd.to_datetime(df[date_col])
    df_f = df.set_index(date_col).sort_index()
    monthly_rev = df_f['revenue'].resample('ME').mean().dropna()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values
        slope, intercept, _, _, _ = stats.linregress(x, y)
        fp = []
        for i in range(1, 4):
            future_x = len(monthly_rev) - 1 + i
            future_val = round(float(intercept + slope * future_x), 2)
            last_date = monthly_rev.index[-1]
            future_period = (last_date + pd.DateOffset(months=i)).strftime('%Y-%m')
            fp.append({"period": future_period, "value": future_val})
        result['forecast_points'] = fp
except Exception:
    pass

