    "Forecasting uses simple OLS linear regression on monthly mean revenue.",
    "notes column contains embedded instruction-like text which was ignored as data."
]

import numpy as np
from scipy import stats

numeric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
segment_cols = ['segment', 'region']
date_col = 'order_date'

# EDA
try:
    eda = {}
    for col in numeric_cols:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# CORRELATIONS
try:
    corr_dict = {}
    num_df = df[numeric_cols].dropna()
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# SEGMENTATION
try:
    seg_results = []
    for seg_col in segment_cols:
        top_groups = df[seg_col].value_counts().head(10).index
        sub = df[df[seg_col].isin(top_groups)]
        for metric in numeric_cols:
            grp = sub.groupby(seg_col)[metric].mean()
            seg_results.append({
                "segment_column": seg_col,
                "metric_column": metric,
                "aggregation": "mean",
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg_col)[numeric_cols[0]].count()
        seg_results.append({
            "segment_column": seg_col,
            "metric_column": numeric_cols[0],
            "aggregation": "count",
            "results": [{"name": str(k), "value": float(v)} for k, v in cnt.items()]
        })
    # Joint breakdown segment x region
    df['_seg_reg'] = df['segment'].astype(str) + '|' + df['region'].astype(str)
    top_joint = df['_seg_reg'].value_counts().head(10).index
    sub_j = df[df['_seg_reg'].isin(top_joint)]
    for metric in numeric_cols:
        grp_j = sub_j.groupby('_seg_reg')[metric].mean()
        seg_results.append({
            "segment_column": "segment|region",
            "metric_column": metric,
            "aggregation": "mean",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp_j.items()]
        })
    result['segments'] = seg_results
except Exception:
    pass

# ANOMALIES
try:
    anomalies = []
    total_cap = 25
    for col in numeric_cols:
        if total_cap <= 0:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()
        q1, q3 = float(s_work.quantile(0.25)), float(s_work.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_work < lo3) | (s_work > hi3)
        flagged_idx = s_work[mask].index.tolist()
        if len(flagged_idx) / len(s) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"[{float(s.quantile(0.25)):.2f}, {float(s.quantile(0.75)):.2f}]",
                "severity": "low",
                "explanation": f"Column {col} is heavy-tailed; extreme-value rate exceeds 5%, not flagged individually."
            })
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = lo3, hi3
        exp_range = f"[{orig_lo:.2f}, {orig_hi:.2f}]"
        for idx in flagged_idx[:total_cap]:
            val = float(df.loc[idx, col])
            w = float(s_work[idx])
            if w > hi5 or w < lo5:
                sev = "critical"
            elif w > hi4 or w < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"Value {val:.4f} in column {col} lies outside expected range {exp_range}."
            })
            total_cap -= 1
            if total_cap <= 0:
                break
    result['anomalies'] = anomalies
except Exception:
    pass

# TRENDS (7d rolling + MoM for non-target-pair metrics)
try:
    df[date_col] = pd.to_datetime(df[date_col])
    df_t = df.set_index(date_col).sort_index()
    trends = []
    for col in numeric_cols:
        daily = df_t[col].resample('D').mean()
        roll = daily.rolling(7).mean().dropna()
        if len(roll) >= 2:
            first7 = float(roll.iloc[0])
            last7 = float(roll.iloc[-1])
            if first7 != 0:
                pct = round((last7 - first7) / abs(first7) * 100, 2)
            else:
                pct = 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": col, "period": "7d_rolling", "direction": direction,
                           "pct_change": pct, "segment": None})
        monthly = df_t[col].resample('ME').mean()
        if len(monthly) >= 2:
            prev_val = float(monthly.iloc[-2])
            curr_val = float(monthly.iloc[-1])
            if prev_val != 0:
                pct_m = round((curr_val - prev_val) / abs(prev_val) * 100, 2)
            else:
                pct_m = 0.0
            direction_m = "up" if pct_m > 1 else ("down" if pct_m < -1 else "flat")
            trends.append({"column": col, "period": "MoM", "direction": direction_m,
                           "pct_change": pct_m, "segment": None})
    result['trends'] = trends
except Exception:
    pass

# FORECASTING (simple linear extrapolation, next 3 months)
try:
    df[date_col] = pd.to_datetime(df[date_col])
    df_f = df.set_index(date_col).sort_index()
    monthly_rev = df_f['revenue'].resample('ME').mean().dropna()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values
        slope, intercept, _, _, _ = stats.linregress(x, y)
        fp = []
        for i in range(1, 4):
            future_x = len(monthly_rev) - 1 + i
            future_val = round(float(intercept + slope * future_x), 2)
            last_date = monthly_rev.index[-1]
            future_period = (last_date + pd.DateOffset(months=i)).strftime('%Y-%m')
            fp.append({"period": future_period, "value": future_val})
        result['forecast_points'] = fp
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    "Duplicate rows (25) were removed prior to analysis.",
    "Pearson r used for correlations; linear association only, not causation.",
    "Anomaly detection uses Q1-3xIQR / Q3+3xIQR; log1p applied for skewed columns.",
    "Forecasting uses simple OLS linear regression on monthly mean revenue.",
    "notes column contains embedded instruction-like text which was ignored as data."
]

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date = ['revenue', 'units', 'discount', 'marketing_spend'], ['segment', 'region', 'customer_email'], 'order_date'
try:
    if True:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
                        result['correlations'][f'{_a}__{_b}'] = round(float(_r), 4)
                        result['builtin'].append(f'corr:{_a}__{_b}')
except Exception:
    pass
try:
    if _date and True:
        _month = pd.to_datetime(df[_date], errors='coerce').dt.to_period('M')
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        _d = pd.to_datetime(df[_date], errors='coerce').dropna()
        _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
        if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
            _month = _month.where(_month != _days.index[-1])
        # One definition of MoM (calendar-month totals), so the built-in value replaces the model's.
        result['trends'] = [t for t in result['trends'] if not (isinstance(t, dict) and t.get('period') == 'MoM' and t.get('column') in _targets)]
        # ponytail: values all in [0, 1] → a rate or flag, compared by month mean; anything else
        # by month total. A semantic layer (Phase 4) can declare the aggregation instead.
        def _mom(_frame, _col):
            _agg = 'mean' if df[_col].dropna().between(0, 1).all() else 'sum'
            _tot = _frame.groupby(_month.loc[_frame.index])[_col].agg(_agg).sort_index()
            if len(_tot) < 2 or _tot.iloc[-2] == 0:
                return None, 0
            _last2 = _month.loc[_frame.index].isin(_tot.index[-2:])
            _n = int(_frame.loc[_last2, _col].notna().sum())
            return round(float((_tot.iloc[-1] / _tot.iloc[-2] - 1) * 100), 2), _n
        for _c in _targets:
            _jobs = [(None, df)]
            if _segs:
                _top = df[_segs[0]].value_counts().head(10).index
                _jobs += [(str(_v), df[df[_segs[0]] == _v]) for _v in _top]
            for _seg, _frame in _jobs:
                _p, _n = _mom(_frame, _c)
                if _p is not None:
                    result['trends'].append({'column': _c, 'period': 'MoM', 'pct_change': _p, 'segment': _seg, 'n': _n,
                                             'direction': 'up' if _p > 0 else 'down' if _p < 0 else 'flat'})
                    result['builtin'].append(f'trend:{_c}' + (f' ({_seg})' if _seg else '') + ':MoM')
except Exception:
    pass
try:
    if len(_segs) >= 2 and 'segmentation' in ['anomaly', 'correlation', 'eda', 'forecasting', 'segmentation', 'trend']:
        _joint = '|'.join(_segs[:2])
        for _c in _targets:
            if any(s.get('segment_column') == _joint and s.get('metric_column') == _c for s in result['segments'] if isinstance(s, dict)):
                continue
            _g = df.groupby(_segs[:2])[_c].mean()
            _n = df.groupby(_segs[:2]).size().sort_values(ascending=False).head(20).index
            result['segments'].append({'segment_column': _joint, 'metric_column': _c, 'aggregation': 'mean',
                                       'results': [{'name': f'{_a}|{_b}', 'value': round(float(_g[(_a, _b)]), 4)} for _a, _b in _n]})
            result['builtin'].append(f'seg:{_joint}/{_c}')
except Exception:
    pass

