try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in num_cols:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (vals < lo) | (vals > hi)
        if mask.sum() / len(vals) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >5% of values as extreme; treated as heavy-tailed natural distribution'
            })
            continue
        flagged = df.loc[mask.index[mask], col]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo) - shift)
            orig_hi = float(np.expm1(hi) - shift)
        else:
            orig_lo, orig_hi = float(lo), float(hi)
        exp_range = f'[{orig_lo:.3f}, {orig_hi:.3f}]'
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx, val in flagged.items():
            v_t = np.log1p(val + shift) if abs(skew) > 2 else val
            if v_t > hi5 or v_t < lo5:
                sev = 'critical'
            elif v_t > hi4 or v_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['medium','high','critical'].index(x['severity']) if x['severity'] in ['medium','high','critical'] else -1, reverse=True)
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

