    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        expected_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        flagged = s_t[mask]
        for idx, val_t in flagged.items():
            orig_val = float(df.loc[idx, col])
            if val_t < lo5 or val_t > hi5:
                sev = 'critical'
            elif val_t < lo4 or val_t > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': expected_range, 'severity': sev,
                'explanation': f'{col} value {orig_val:.4g} lies outside expected range {expected_range}'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
