        skew = float(s.skew())
        shift = 0
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo_ext = Q1 - 3 * IQR
        hi_ext = Q3 + 3 * IQR
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s) > 0.05:
            anomaly_records.append({
