import numpy as np
from scipy import stats

# EDA
try:
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r = num_df[c1].corr(num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    for seg in seg_cols:
        top_groups = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top_groups)]
        for metric in metric_cols:
            agg = sub.groupby(seg)[metric].mean()
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in agg.items()]
            })
        cnt = sub.groupby(seg)[metric_cols[0]].count()
        result['segments'].append({
            'segment_column': seg, 'metric_column': metric_cols[0],
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': float(v)} for k, v in cnt.items()]
        })
    # Two-column breakdown segment|region
    df['_seg_reg'] = df['segment'].astype(str) + '|' + df['region'].astype(str)
    top2 = df['_seg_reg'].value_counts().head(10).index
    sub2 = df[df['_seg_reg'].isin(top2)]
    for metric in metric_cols:
        agg2 = sub2.groupby('_seg_reg')[metric].mean()
        result['segments'].append({
            'segment_column': 'segment|region', 'metric_column': metric,
            'aggregation': 'mean',
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in agg2.items()]
        })
except Exception:
    pass

# ANOMALIES
try:
    anomaly_records = []
    skip_cols = ['order_id']
    for col in metric_cols:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo_ext = Q1 - 3 * IQR
        hi_ext = Q3 + 3 * IQR
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not flagged individually'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_ext) - shift)
            hi_orig = float(np.expm1(hi_ext) - shift)
        else:
            lo_orig, hi_orig = float(lo_ext), float(hi_ext)
        exp_range = f'[{lo_orig:.4g}, {hi_orig:.4g}]'
        for idx in flagged.index:
            orig_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val > Q3 + 5 * IQR:
                sev = 'critical'
            elif t_val > Q3 + 4 * IQR:
                sev = 'high'
            elif t_val > Q3 + 3 * IQR or t_val < Q1 - 3 * IQR:
                sev = 'medium'
            else:
                sev = 'low'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

# TRENDS (7d rolling)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    daily = df.groupby('order_date')[metric_cols].mean().sort_index()
    for col in metric_cols:
        roll = daily[col].rolling(7).mean().dropna()
        if len(roll) >= 2:
            first_val = float(roll.iloc[0])
            last_val = float(roll.iloc[-1])
            if first_val != 0:
                pct = round((last_val - first_val) / abs(first_val) * 100, 2)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col, 'period': '7d_rolling',
                'direction': direction, 'pct_change': pct, 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly revenue)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly = df.groupby('_ym')['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        for step in [1, 2, 3]:
            period_label = str(monthly.index[-1] + step)
            pred_val = round(float(intercept + slope * (len(monthly) - 1 + step)), 2)
            result['forecast_points'].append({'period': period_label, 'value': pred_val})
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    'Correlations are Pearson r (linear only); not causal.',
    'Anomaly detection uses Q1-3xIQR / Q3+3xIQR extreme boundaries; log1p applied when |skew|>2.',
    'Forecasting uses OLS linear regression on monthly revenue totals; assumes linear trend.',
    '7d rolling trend compares first vs last rolling-mean value across the full date range.',
    'customer_email excluded from segmentation due to high cardinality (PII masked).'
]

